local function value(v)return v==nil and L["UNKNOWN"]or tostring(v)end
local function field(value)if type(value)~="table"then return value==nil and L["UNKNOWN"]or tostring(value)end;if value.status=="unknown"then return L["UNKNOWN"]end;if value.value~=nil then return tostring(value.value)end;if value.count~=nil then return tostring(value.count)end;if value.level~=nil then return tostring(value.level)end;if value.name~=nil then return tostring(value.name)end;return L["PRESENT"]end
local function refresh(view,context,definition)local C=HolyStorm.CharacterUI;local ok,reason=C:CanUseTab(definition);if not ok then C:SetView(view,L["DISPLAY_NAME"],{reason=="PERMISSION"and L["PERMISSION_DENIED"]or L["MODULE_DISABLED"]});return end;local snapshot,meta=C:GetSnapshot(context.characterUUID,"delves");local status=C:GetDataStatus(context.characterUUID,"delves");if not snapshot then C:SetView(view,L["DISPLAY_NAME"],{L["NO_DELVES"]},status);return end;local lines={string.format(L["SEASON"],value(snapshot.seasonNumber)),L["GREAT_VAULT"]..": "..value(snapshot.weeklyProgress),L["BOUNTIFUL"]..": "..field(snapshot.bountiful),L["KEY_FRAGMENTS"]..": "..field(snapshot.keyFragments),L["COMPLETED_KEYS"]..": "..field(snapshot.completedKeys),L["TREASURE_MAP"]..": "..field(snapshot.treasureMap),L["MAP_USED"]..": "..field(snapshot.treasureMapUsed),L["FLUTE"]..": "..field(snapshot.flute),L["MINI_ROGUE"]..": "..field(snapshot.miniRogue),L["COMPANION"]..": "..field(snapshot.companion)};for index,a in ipairs(snapshot.activities or{})do lines[#lines+1]=string.format("%s  %s",string.format(L["ACTIVITY"],a.index or index),string.format(L["PROGRESS_FORMAT"],value(a.progress),value(a.threshold),value(a.level)))end;C:SetView(view,L["DISPLAY_NAME"],lines,status,meta,{[1]="accent"})end
